style.css:
@-moz-document domain("roblox.com") {
/* Fondo personalizado */
    body {
        background-color: #0d1117 !important;
        background-image: url(https://i.pinimg.com/736x/5c/92/85/5c928565b35198e19c03eade464439b7.jpg) !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
        color: #e6edf3 !important;
    }

    /* Capa oscura encima del fondo para que el texto se vea bien */
    body::before {
        content: "";
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.6);
        z-index: 0;
        pointer-events: none;
    }

    /* Asegurar que el contenido esté encima del overlay */
    body * {
        position: relative;
        z-index: 1;
    }

    /* Barra superior */
    .navbar, .rbx-navbar {
        background: #0f141b !important;
        border-bottom: 1px solid #00f2ff !important;
    }

    /* Tarjetas de juegos */
    .game-card-container,
    .game-card,
    .item-card-container {
        background: #161b22 !important;
        border-radius: 12px !important;
        transition: 0.3s ease !important;
    }

    .game-card-container:hover,
    .item-card-container:hover {
        transform: translateY(-5px) !important;
        box-shadow: 0 0 15px #00f2ff !important;
    }

    /* Botones */
    .btn-primary, .btn-secondary, button {
        background: linear-gradient(45deg, #00f2ff, #0077ff) !important;
        border: none !important;
        border-radius: 8px !important;
        color: white !important;
        transition: 0.3s ease !important;
    }

    .btn-primary:hover, button:hover {
        box-shadow: 0 0 12px #00f2ff !important;
        transform: scale(1.05) !important;
    }

    /* Inputs */
    input, textarea {
        background-color: #1c2128 !important;
        border: 1px solid #00f2ff !important;
        color: white !important;
        border-radius: 6px !important;
    }

    /* Perfil y paneles */
    .profile-header-top,
    .section-content,
    .container-main {
        background-color: #161b22 !important;
        border-radius: 12px !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(#00f2ff, #0077ff);
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #0d1117;
    }
}
